def main():
    applied, present, problems = 0, 0, []

    src = open(GATES, encoding='utf-8').read()
    if GATES_NEW not in src:
        if GATES_OLD not in src:
            problems.append('the EXTRA line in dev/gates.sh is not the expected one')
        else:
            applied += 1
            if not CHECK:
                open(GATES, 'w', encoding='utf-8').write(src.replace(GATES_OLD, GATES_NEW, 1))

    for rel, old, new in RETARGETS:
        path = os.path.join(ROOT, rel)
        body = open(path, encoding='utf-8').read()
        if new in body:
            present += 1
            continue
        if body.count(old) != 1:
            problems.append('%s (the 80.0 text was found %d times)' % (rel, body.count(old)))
            continue
        applied += 1
        if not CHECK:
            open(path, 'w', encoding='utf-8').write(body.replace(old, new, 1))

    for p in problems:
        print('  ! ' + p)
    print('patch-gate-8001: %d applied, %d already in place' % (applied, present))
    if problems:
        sys.exit(1)
    if CHECK and applied:
        print('patch-gate-8001 --check: the tree is not fully retargeted')
        sys.exit(1)


if __name__ == '__main__':
    main()

